a=commandArgs(TRUE);o=a[1];p=read.delim(file.path(o,'gwas_results.tsv'));stopifnot(nrow(p)>0,all(p$p>0&p$p<=1));png(file.path(o,'manhattan_subset.png'),width=1000,height=600);plot(p$position,-log10(p$p),pch=20,col='navy',xlab='Chr01 position (5000-record validation subset)',ylab='-log10(p)');abline(h=-log10(.05/nrow(p)),col='red',lty=2);dev.off();png(file.path(o,'qq_subset.png'),width=600,height=600);plot(-log10(ppoints(nrow(p))),-log10(sort(p$p)),pch=20,xlab='Expected -log10(p)',ylab='Observed -log10(p)');abline(0,1,col='red');dev.off()
